mapper.select:
WITH RECURSIVE org_tree AS ( SELECT id AS _id, parent_id AS _pid FROM organization WHERE id = #{id}
UNION ALL
SELECT o.id AS _id, o.parent_id AS _pid FROM organization o JOIN org_tree ot ON o.id = ot._pid ) SELECT DATA.* FROM org_tree ID JOIN organization DATA ON ID._id = DATA.id ORDER BY "level";
